# -*- coding: utf-8 -*-
"""生成 `rotation_sort_golden_test.go`：用**原版** `_candidate_sort_frame`
（portfolio_rotation_logic.py:1582-1601）跑出候选池的排序结果。

为什么需要：那是一个**八键排序**，`ascending` 方向是
`[False, True, False, True, False, False, False, True]` ——
抄反任何一位（比如 `signal_age` 该升序却写成降序）都不会报错，
只会静默选出不同的票、配对到不同的候选。这种"方向抄反"用读代码几乎看不出来。

做法：故意让所有行的 `total_score` **相同**，这样排序完全由后七个键决定；
再逐层放开 tie-break（信号优先级 → 信号分 → 信号年龄 → rs20 → 修复分 →
研究分 → 代码），每一层都同时给出"该键不同"与"该键相同"的行。

用法：

    python internal/score/testdata/gen_rotation_sort_golden.py \
        --original "D:\\workspace\\python\\stock\\tushare-stock-tonyz\\pythonProject\\pythonProject" \
        --out internal/score/rotation_sort_golden_test.go
"""

from __future__ import annotations

import argparse
import json
import os
import shutil
import subprocess
import sys


def go_str(value) -> str:
    return json.dumps(str(value), ensure_ascii=False)


def go_float(value) -> str:
    return repr(float(value))


def row(code, **kw):
    base = {
        "ts_code": code,
        "total_score": 70.0,
        "active_signal_type": "",
        "active_signal_score": 0.0,
        "signal_age": 999,
        "relative_strength_20d": 0.0,
        "repair_score": 0.0,
        "research_score": 0.0,
    }
    base.update(kw)
    return base


def build_rows():
    """返回若干组行；每组内部 total_score 相同，逐层压 tie-break。"""
    groups = {}

    # 第 1 层：信号优先级（buy=0 < candidate_buy=1 < 其他=2），方向 ASC
    groups["signal_priority"] = [
        row("000003", active_signal_type="", active_signal_score=99.0, signal_age=1),
        row("000002", active_signal_type="candidate_buy", active_signal_score=99.0, signal_age=1),
        row("000001", active_signal_type="buy", active_signal_score=1.0, signal_age=99),
    ]
    # 第 2 层：信号分 DESC（同一优先级内）
    groups["signal_score"] = [
        row("000001", active_signal_type="buy", active_signal_score=1.0, signal_age=1),
        row("000003", active_signal_type="buy", active_signal_score=3.0, signal_age=1),
        row("000002", active_signal_type="buy", active_signal_score=2.0, signal_age=1),
    ]
    # 第 3 层：信号年龄 ASC
    groups["signal_age"] = [
        row("000001", active_signal_type="buy", signal_age=9),
        row("000002", active_signal_type="buy", signal_age=1),
        row("000003", active_signal_type="buy", signal_age=5),
    ]
    # 第 4 层：rs20 DESC
    groups["relative_strength"] = [
        row("000001", relative_strength_20d=-5.0),
        row("000002", relative_strength_20d=5.0),
        row("000003", relative_strength_20d=0.0),
    ]
    # 第 5 层：修复分 DESC
    groups["repair"] = [
        row("000001", relative_strength_20d=1.0, repair_score=1.0),
        row("000002", relative_strength_20d=1.0, repair_score=3.0),
        row("000003", relative_strength_20d=1.0, repair_score=2.0),
    ]
    # 第 6 层：研究分 DESC
    groups["research"] = [
        row("000001", relative_strength_20d=1.0, repair_score=1.0, research_score=1.0),
        row("000002", relative_strength_20d=1.0, repair_score=1.0, research_score=3.0),
        row("000003", relative_strength_20d=1.0, repair_score=1.0, research_score=2.0),
    ]
    # 第 7 层：代码 ASC（其余全同）
    groups["code"] = [
        row("000300"), row("000100"), row("000200"),
    ]
    # 总分不同 → 总分 DESC 必须压过所有其它键
    groups["total_score_first"] = [
        row("000001", total_score=60.0, active_signal_type="buy", active_signal_score=99.0,
            signal_age=1, relative_strength_20d=99.0),
        row("000002", total_score=90.0),
        row("000003", total_score=75.0),
    ]
    # 全同 → 稳定排序，保持原顺序（用反向的代码顺序验证不是"按代码兜底"）
    groups["all_tied"] = [row("000900"), row("000100"), row("000500")]

    # 一个"全键组合"的大组：8 个键各给几种取值，让多层 tie-break 交织
    mixed = []
    for i, (sig, sscore, age, rs, rep, res) in enumerate([
        ("buy", 10.0, 1, 5.0, 1.0, 0.0),
        ("buy", 10.0, 2, 5.0, 1.0, 0.0),
        ("buy", 9.0, 1, 5.0, 1.0, 0.0),
        ("candidate_buy", 99.0, 1, 9.0, 9.0, 9.0),
        ("", 99.0, 1, 9.0, 9.0, 9.0),
        ("buy", 10.0, 1, 5.0, 2.0, 0.0),
        ("buy", 10.0, 1, 5.0, 1.0, 1.0),
        ("buy", 10.0, 1, 6.0, 0.0, 0.0),
    ]):
        code = "9%05d" % i
        mixed.append(row(code, active_signal_type=sig, active_signal_score=sscore,
                         signal_age=age, relative_strength_20d=rs,
                         repair_score=rep, research_score=res))
    groups["mixed"] = mixed

    return groups


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--original", required=True)
    parser.add_argument("--out", required=True)
    args = parser.parse_args()

    if args.original not in sys.path:
        sys.path.insert(0, args.original)

    import pandas as pd  # noqa: E402
    import portfolio_rotation_logic as rot  # noqa: E402

    lines = []
    lines.append("// Code generated by testdata/gen_rotation_sort_golden.py; DO NOT EDIT.")
    lines.append("//")
    lines.append("// 黄金值由**原版 _candidate_sort_frame**（portfolio_rotation_logic.py:1582-1601）跑出。")
    lines.append("package score")
    lines.append("")
    lines.append("type goldenSortRow struct {")
    lines.append("\tCode string")
    lines.append("\tTotalScore float64")
    lines.append("\tSignalType string")
    lines.append("\tSignalScore float64")
    lines.append("\tSignalAge int")
    lines.append("\tRelativeStrength20D float64")
    lines.append("\tRepairScore float64")
    lines.append("\tResearchScore float64")
    lines.append("}")
    lines.append("")
    lines.append("type goldenSortCase struct {")
    lines.append("\tDesc string")
    lines.append("\tRows []goldenSortRow")
    lines.append("\tOrder []string")
    lines.append("}")
    lines.append("")
    lines.append("var goldenSortCases = []goldenSortCase{")

    groups = build_rows()
    for desc, rows in groups.items():
        frame = pd.DataFrame(rows)
        ordered = rot._candidate_sort_frame(frame)
        order = [str(code) for code in ordered["ts_code"].tolist()]
        lines.append("\t{")
        lines.append("\t\tDesc: %s," % go_str(desc))
        lines.append("\t\tRows: []goldenSortRow{")
        for r in rows:
            lines.append("\t\t\t{%s, %s, %s, %s, %d, %s, %s, %s}," % (
                go_str(r["ts_code"]), go_float(r["total_score"]),
                go_str(r["active_signal_type"]), go_float(r["active_signal_score"]),
                int(r["signal_age"]), go_float(r["relative_strength_20d"]),
                go_float(r["repair_score"]), go_float(r["research_score"])))
        lines.append("\t\t},")
        lines.append("\t\tOrder: []string{%s}," % ", ".join(go_str(c) for c in order))
        lines.append("\t},")
    lines.append("}")
    lines.append("")

    os.makedirs(os.path.dirname(os.path.abspath(args.out)), exist_ok=True)
    with open(args.out, "w", encoding="utf-8", newline="\n") as handle:
        handle.write("\n".join(lines))
    gofmt = shutil.which("gofmt")
    if gofmt:
        subprocess.run([gofmt, "-w", args.out], check=True)
    print(f"wrote {args.out}: {len(groups)} groups")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
